const panel=document.createElement('details');panel.id='learning-cycle';panel.className='panel learning-cycle';panel.innerHTML='<summary>Predict → change → compare → solve</summary><div class="cycle-body"></div>';const main=document.querySelector('main'),anchor=main.querySelector('.model-layout,.two-col,.layout')||document.getElementById('workbench');if(/\/labs(?:\.html)?$/.test(location.pathname)&&document.getElementById('engine'))document.getElementById('engine').after(panel);else if(anchor)anchor.after(panel);else{const after=main.querySelector('section:has(svg),.plot-card');if(after)after.after(panel);else main.append(panel);}const body=panel.querySelector('.cycle-body');let currentId=null,lastContext=null;
function context(){return window.MT_LEARNING_CYCLE_CONTEXT.read();}
function complete(id){try{const stored=read('mt-student-cycles-completed-v1'),known=new Set((window.MT_INTERACTIVE_MODULES||[]).map(m=>m.id)),ids=new Set(Array.isArray(stored)?stored.filter(x=>known.has(x)):[]);ids.add(id);write('mt-student-cycles-completed-v1',[...ids]);}catch{}}
