function storage(e){return e.storageState==='saved'?'This learning cycle is saved on this device.':e.storageState==='incompatible'?'A newer saved format is preserved. This learning cycle is available for the current session.':'Browser storage is unavailable. This learning cycle lasts for the current session.';}
