function focus(){(body.querySelector('#cycle-applied h3')||body.querySelector('h3'))?.focus({preventScroll:true});}
function adjust(){const scope=document.querySelector('#'+(currentId==='controls'?'signal':currentId)+'-form')||document.getElementById('experiment')||document.getElementById('cargo-form')||document.querySelector('.layout>.controls');if(!scope)return;const details=scope.closest('details');if(details)details.open=true;scope.scrollIntoView({block:'start',behavior:'auto'});const first=[...scope.querySelectorAll('input:not([type=file]),select')].find(n=>!n.closest('[hidden]'));first?.focus({preventScroll:true});}
function refresh(){if(!document?.body||!panel.open)return;try{const c=context();if(!currentId||c.id!==currentId){show();return;}const e=engine(currentId),s=e.state;if(s.stage==='predict'){const select=body.querySelector('#cycle-metric'),preview=body.querySelector('#cycle-baseline-preview');if(select&&preview){const before=select.value;if([...select.options].map(o=>o.value).join('|')!==c.metrics.map(q=>q.id).join('|')){select.innerHTML=c.metrics.map(q=>'<option value="'+escape(q.id)+'">'+escape(q.label)+(q.unit?' ('+escape(q.unit)+')':'')+'</option>').join('');if(c.metrics.some(q=>q.id===before))select.value=before;}const q=c.metrics.find(q=>q.id===select.value);preview.textContent='Current result: '+fmt(q.value)+(q.unit?' '+q.unit:'');}return;}const status=body.querySelector('#cycle-state-status');if(status)status.textContent=s.comparison&&c.fingerprint!==s.comparison.fingerprint?'The model changed after this comparison. Compare the current state again before checking an answer.':s.baseline&&c.fingerprint!==s.baseline.fingerprint?'Model inputs changed. The current state is ready to compare.':'Change at least one model input, then compare.';}catch(e){const status=body.querySelector('#cycle-state-status')||body.querySelector('.cycle-error');if(status)status.textContent='The current model is invalid: '+e.message;}}

let queued=false;function schedule(event){if(event?.target?.closest?.('.learning-cycle,.study-session,.diagram-tools,.diagram-pan-tools'))return;if(queued)return;queued=true;queueMicrotask(()=>{queued=false;refresh();});}
