for(const form of document.querySelectorAll('form')){const button=document.createElement('button');button.type='button';button.className='cycle-return';button.textContent='Return to learning cycle ↓';button.onclick=()=>{panel.open=true;panel.scrollIntoView({block:'start',behavior:'auto'});panel.querySelector('summary').focus();};form.append(button);}
window.MT_LEARNING_CYCLE_UI={read:context,get engine(){return currentId?engine(currentId):null},show};show();
